public static String reverse(String s) {
    char[] c = s.toCharArray();
    for (int i = 0, j = c.length - 1; i < j; i++, j--) {
        char t = c[i]; c[i] = c[j]; c[j] = t;
    }
    return new String(c);
}

def reverse(s: str) -> str:
    chars = list(s)
    i, j = 0, len(chars) - 1
    while i < j:
        chars[i], chars[j] = chars[j], chars[i]
        i += 1; j -= 1
    return "".join(chars)

public static boolean isPalindrome(String s) {
    String t = s.toLowerCase().replaceAll("[^a-z0-9]", "");
    int i = 0, j = t.length() - 1;
    while (i < j) if (t.charAt(i++) != t.charAt(j--)) return false;
    return true;
}

def is_palindrome(s: str) -> bool:
    t = [ch.lower() for ch in s if ch.isalnum()]
    return t == t[::-1]

public static Map<Character, Integer> freq(String s) {
    Map<Character, Integer> m = new LinkedHashMap<>();
    for (char c : s.toCharArray()) m.merge(c, 1, Integer::sum);
    return m;
}

