def is_anagram(a: str, b: str) -> bool:
    return Counter(a) == Counter(b)

public static String compress(String s) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < s.length(); ) {
        int j = i;
        while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
        sb.append(s.charAt(i)).append(j - i);
        i = j;
    }
    return sb.toString();
}

def compress(s: str) -> str:
    out, i = [], 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(f"{s[i]}{j - i}")
        i = j
    return "".join(out)

public static boolean isValid(String s) {
    Deque<Character> st = new ArrayDeque<>();
    Map<Character, Character> pair = Map.of(')', '(', ']', '[', '}', '{');
    for (char c : s.toCharArray()) {
        if (pair.containsValue(c)) st.push(c);
        else if (st.isEmpty() || st.pop() != pair.get(c)) return false;
    }
    return st.isEmpty();
}

def is_valid(s: str) -> bool:
    pair = {")": "(", "]": "[", "}": "{"}
    stack = []
    for c in s:
        if c in pair.values():
            stack.append(c)
        elif not stack or stack.pop() != pair[c]:
            return False
    return not stack

public static Set<Integer> duplicates(int[] a) {
    Set<Integer> seen = new HashSet<>(), dup = new LinkedHashSet<>();
    for (int x : a) if (!seen.add(x)) dup.add(x);
    return dup;
}

def duplicates(a: list[int]) -> list[int]:
    seen, dup = set(), []
    for x in a:
        if x in seen and x not in dup:
            dup.append(x)
        seen.add(x)
    return dup

public static int[] twoSum(int[] a, int target) {
    Map<Integer, Integer> idx = new HashMap<>();
    for (int i = 0; i < a.length; i++) {
        Integer j = idx.get(target - a[i]);
        if (j != null) return new int[]{j, i};
        idx.put(a[i], i);
    }
    return new int[0];
}

def two_sum(a: list[int], target: int):
    idx = {}
    for i, x in enumerate(a):
        if target - x in idx:
            return [idx[target - x], i]
        idx[x] = i
    return []

public static int missing(int[] a, int n) {
    long expected = (long) n * (n + 1) / 2;
    long sum = 0;
    for (int x : a) sum += x;
    return (int) (expected - sum);
}

public static Integer secondLargest(int[] a) {
    Integer first = null, second = null;
    for (int x : a) {
        if (first == null || x > first) { second = first; first = x; }
        else if (x != first && (second == null || x > second)) second = x;
    }
    return second;
}

def second_largest(a: list[int]):
    first = second = None
    for x in a:
        if first is None or x > first:
            first, second = x, first
        elif x != first and (second is None or x > second):
            second = x
    return second

public static void moveZeros(int[] a) {
    int k = 0;
    for (int x : a) if (x != 0) a[k++] = x;
    while (k < a.length) a[k++] = 0;
}

def move_zeros(a: list[int]) -> None:
    k = 0
    for x in a:
        if x != 0:
            a[k] = x; k += 1
    for i in range(k, len(a)):
        a[i] = 0

